-- Guarded cleanup of inert legacy resource child pools, batch 04.
-- Physical gameobject rows are untouched.
START TRANSACTION;
DELETE pp FROM pool_pool pp LEFT JOIN pool_creature pc ON pc.pool_entry=pp.pool_id LEFT JOIN pool_gameobject pg ON pg.pool_entry=pp.pool_id LEFT JOIN pool_quest pq ON pq.pool_entry=pp.pool_id LEFT JOIN game_event_pool gep ON gep.pool_entry=pp.pool_id LEFT JOIN pool_pool child ON child.mother_pool=pp.pool_id WHERE pp.pool_id IN (1795,1799,1802,1804,1809,1813,1820,1823,1827,1829,1838,1839,1840,1841,1843,1845,1847,1848,1849,1851,1853,1854,1855,1856,1857,1858,1859,1860,1861,1862,1865,1867,1868,1871,1872,1874,1876,1877,1878,1881,1882,1885,1887,1888,1891,1892,1893,1894,1895,1896) AND pc.guid IS NULL AND pg.guid IS NULL AND pq.entry IS NULL AND gep.pool_entry IS NULL AND child.pool_id IS NULL;
DELETE pt FROM pool_template pt LEFT JOIN pool_creature pc ON pc.pool_entry=pt.entry LEFT JOIN pool_gameobject pg ON pg.pool_entry=pt.entry LEFT JOIN pool_quest pq ON pq.pool_entry=pt.entry LEFT JOIN game_event_pool gep ON gep.pool_entry=pt.entry LEFT JOIN pool_pool pp_child ON pp_child.pool_id=pt.entry LEFT JOIN pool_pool pp_mother ON pp_mother.mother_pool=pt.entry WHERE pt.entry IN (1795,1799,1802,1804,1809,1813,1820,1823,1827,1829,1838,1839,1840,1841,1843,1845,1847,1848,1849,1851,1853,1854,1855,1856,1857,1858,1859,1860,1861,1862,1865,1867,1868,1871,1872,1874,1876,1877,1878,1881,1882,1885,1887,1888,1891,1892,1893,1894,1895,1896) AND pc.guid IS NULL AND pg.guid IS NULL AND pq.entry IS NULL AND gep.pool_entry IS NULL AND pp_child.pool_id IS NULL AND pp_mother.pool_id IS NULL;
COMMIT;

